settings.custom_css:
selector{direction:rtl;box-sizing:border-box;overflow:hidden;color:#45215e;font-family:DgsPortal,Estedad,Tahoma,sans-serif;min-width:0}
selector>.elementor-container{display:grid!important;grid-template-columns:1fr 1.08fr;gap:14px;align-items:center;max-width:none!important}
selector>.elementor-container>.elementor-column{width:auto!important;min-width:0}
selector .elementor-widget-wrap{min-width:0;align-content:center;box-sizing:border-box}
selector .elementor-widget:not(:last-child){margin-bottom:8px}
selector p{margin:0;line-height:1.9}
selector h1,selector h2,selector h3{margin:0;line-height:1.65;overflow-wrap:normal!important}
selector a{text-decoration:none}
selector svg{flex-shrink:0}
selector .elementor-button{line-height:1.7;min-height:0;box-shadow:none}
selector .elementor-widget-text-editor{font-size:13px;line-height:1.9}
selector .dse-live,selector .dsh-carousel,selector .dsh-featured-main{min-width:0}
selector .dg-empty-inline{font-size:12px;padding:16px;border-radius:10px}
@media(max-width:767px){selector>.elementor-container{grid-template-columns:1fr!important;gap:14px}selector{padding:14px!important}selector .elementor-heading-title{overflow-wrap:normal!important}}
:root{--det-home-reference:url("data:image/jpeg;base64,");}selector .dsh-reference{background-image:var(--det-home-reference);background-size:210.7% 614.4%;background-position:1.5% 4.04%;background-repeat:no-repeat}selector .dse-picture-frame{mask-image:none;min-height:0;max-height:none}
selector{padding:0!important}selector>.elementor-container{gap:0}selector>.elementor-container>.elementor-column:first-child>.elementor-widget-wrap{padding:20px}selector .dse-picture-frame{border-radius:14px;mask-image:linear-gradient(to right,#000 82%,transparent)}selector .elementor-widget-button{margin-bottom:7px!important}@media(max-width:767px){selector .dse-picture-frame{mask-image:none}}
